   663  int processCertificate(struct ndpi_detection_module_struct *ndpi_struct,
   664                         struct ndpi_flow_struct *flow) {
   665    struct ndpi_packet_struct *packet = &ndpi_struct->packet;
   666    int is_dtls = packet->udp ? 1 : 0;
   667    u_int32_t certificates_length, length = (packet->payload[1] << 16) + (packet->payload[2] << 8) + packet->payload[3];
   668    u_int32_t certificates_offset = 7 + (is_dtls ? 8 : 0);
   669    u_int8_t num_certificates_found = 0;
   670    SHA1_CTX srv_cert_fingerprint_ctx ;
   671
   672  #ifdef DEBUG_TLS
   673    printf("[TLS] %s() [payload_packet_len=%u][direction: %u][%02X %02X %02X %02X %02X %02X...]\n",
   674           __FUNCTION__, packet->payload_packet_len,
   675           packet->packet_direction,
   676           packet->payload[0], packet->payload[1], packet->payload[2],
   677           packet->payload[3], packet->payload[4], packet->payload[5]);
   678  #endif
   679
   680    if((packet->payload_packet_len != (length + 4 + (is_dtls ? 8 : 0))) || (packet->payload[1] != 0x0) ||
   681       certificates_offset >= packet->payload_packet_len) {
   682      ndpi_set_risk(ndpi_struct, flow, NDPI_MALFORMED_PACKET);
   683      return(-1); /* Invalid length */
   684    }
   685
   686    certificates_length = (packet->payload[certificates_offset - 3] << 16) +
   687                          (packet->payload[certificates_offset - 2] << 8) +
   688                          packet->payload[certificates_offset - 1];
   689
   690    if((packet->payload[certificates_offset - 3] != 0x0) || ((certificates_length+3) != length)) {
   691      ndpi_set_risk(ndpi_struct, flow, NDPI_MALFORMED_PACKET);
   692      return(-2); /* Invalid length */
   693    }
   694
   695    /* Now let's process each individual certificates */
   696    while(certificates_offset < certificates_length) {
   697      u_int32_t certificate_len = (packet->payload[certificates_offset] << 16) + (packet->payload[certificates_offset+1] << 8) + packet->payload[certificates_offset+2];
   698
   699      /* Invalid lenght */
   700      if((certificate_len == 0)
   701         || (packet->payload[certificates_offset] != 0x0)
   702         || ((certificates_offset+certificate_len) > (4+certificates_length+(is_dtls ? 8 : 0)))) {
   703  #ifdef DEBUG_TLS
   704        printf("[TLS] Invalid length [certificate_len: %u][certificates_offset: %u][%u vs %u]\n",
   705               certificate_len, certificates_offset,
   706               (certificates_offset+certificate_len),
   707               certificates_length);
   708  #endif
   709        break;
   710      }
   711
   712      certificates_offset += 3;
   713  #ifdef DEBUG_TLS
   714      printf("[TLS] Processing %u bytes certificate [%02X %02X %02X]\n",
   715             certificate_len,
   716             packet->payload[certificates_offset],
   717             packet->payload[certificates_offset+1],
   718             packet->payload[certificates_offset+2]);
   719  #endif
   720
   721      if(num_certificates_found++ == 0) /* Dissect only the first certificate that is the one we care */ {
   722        /* For SHA-1 we take into account only the first certificate and not all of them */
   723
   724        SHA1Init(&srv_cert_fingerprint_ctx);
   725
   726  #ifdef DEBUG_CERTIFICATE_HASH
   727        {
   728          u_int32_t i;
   729
   730          for(i=0;i<certificate_len;i++)
   731            printf("%02X ", packet->payload[certificates_offset+i]);
   732
   733          printf("\n");
   734        }
   735  #endif
   736
   737        SHA1Update(&srv_cert_fingerprint_ctx,
   738                   &packet->payload[certificates_offset],
   739                   certificate_len);
   740
   741        SHA1Final(flow->protos.tls_quic.sha1_certificate_fingerprint, &srv_cert_fingerprint_ctx);
   742
   743        flow->l4.tcp.tls.fingerprint_set = 1;
   744
   745        uint8_t * sha1 = flow->protos.tls_quic.sha1_certificate_fingerprint;
   746        const size_t sha1_siz = sizeof(flow->protos.tls_quic.sha1_certificate_fingerprint);
   747        char sha1_str[20 /* sha1_siz */ * 2 + 1];
   748        static const char hexalnum[] = "0123456789ABCDEF";
   749        size_t i;
   750        for (i = 0; i < sha1_siz; ++i) {
   751          u_int8_t lower = (sha1[i] & 0x0F);
   752          u_int8_t upper = (sha1[i] & 0xF0) >> 4;
   753          sha1_str[i*2] = hexalnum[upper];
   754          sha1_str[i*2 + 1] = hexalnum[lower];
   755        }
   756        sha1_str[sha1_siz * 2] = '\0';
   757
   758  #ifdef DEBUG_TLS
   759        printf("[TLS] SHA-1: %s\n", sha1_str);
   760  #endif
